import hashlib, json, sys
from pathlib import Path
root = Path(sys.argv[1])
repo = Path(sys.argv[2])
sys.path.insert(0, str(repo / ".claude/skills/ld-s10y-lesson/tools"))
import edition
manifest = json.loads((repo / ".intentfold/tickets/STEMROBIN-188/tmp/n68-modern-text-author-inputs-01/manifest.json").read_text())
profile = json.loads((repo / ".claude/skills/ld-s10y-lesson/profiles/modern-us-neutral.json").read_text())
forbidden = profile["forbidden_terms"] + profile["forbidden_person_names"]
records, errors = [], []
for name, binding, collection, stable_fields in [("lesson.template.json", manifest["rawLesson"], "prose", ["kind", "id", "label", "printed_page", "source_refs"]), ("exercises.template.json", manifest["rawExercises"], "exercises", ["number", "source_number", "group", "group_id", "pages", "figure_refs", "figures"])]:
    candidate = json.loads((root / name).read_text())
    raw_bytes = Path(binding["path"]).read_bytes()
    raw = json.loads(raw_bytes)
    if hashlib.sha256(raw_bytes).hexdigest() != binding["sha256"]: errors.append(name + ": raw binding drift")
    if candidate["source"]["data"] != raw or candidate["source"]["sha256"] != binding["sha256"]: errors.append(name + ": embedded raw snapshot drift")
    if len(candidate[collection]) != len(raw[collection]): errors.append(name + ": object count drift")
    if collection == "prose":
        for field in edition.IDENTITY_FIELDS:
            if candidate.get(field) != raw.get(field): errors.append(name + ": identity drift: " + field)
        if candidate["figures"] != raw["figures"]: errors.append(name + ": lesson figure-reference drift")
    else:
        if candidate["lesson"] != raw["lesson"] or candidate["count"] != raw["count"]: errors.append(name + ": exercise document identity drift")
    for i, (item, source) in enumerate(zip(candidate[collection], raw[collection])):
        refs = source.get("source_refs", source.get("pages"))
        label = name + "." + collection + "[" + str(i) + "]"
        item_errors = edition.validate_text(source["text"], item["text"], item.get("changes"), item.get("numeric_changes"), label, forbidden, item.get("historical_entities"))
        identities = all(item.get(field) == source.get(field) and (field in item) == (field in source) for field in stable_fields)
        if not identities: item_errors.append(label + ": identity or source-ref drift")
        if item.get("source_text") != source["text"]: item_errors.append(label + ": source_text drift")
        if item.get("numeric_changes") != [] or item.get("historical_entities") != []: item_errors.append(label + ": unexpected numeric/historical declaration")
        if any(edition.MATH_BOUNDARY_PUNCTUATION.search(match.group(1) or match.group(2)) for match in edition.MATH.finditer(item["text"])): item_errors.append(label + ": CJK punctuation inside math")
        if collection == "exercises" and item["lines"] != item["text"].split("\n"): item_errors.append(label + ": lines/text mismatch")
        record = {"target": collection + "[" + str(i) + "]", "number": item.get("number"), "kind": item.get("kind", "exercise"), "source_refs": refs, "source_text_sha256": hashlib.sha256(source["text"].encode()).hexdigest(), "modern_text_sha256": hashlib.sha256(item["text"].encode()).hexdigest(), "text_changed": item["text"] != source["text"], "changes": item["changes"], "numeric_changes": item["numeric_changes"], "historical_entities": item["historical_entities"], "identities_preserved": identities, "math_signature_preserved": edition.math_signature(source["text"]) == edition.math_signature(item["text"]), "native_number_signature_preserved": edition.number_signature(edition.normalize_numbered_subparts(source["text"])) == edition.number_signature(edition.normalize_numbered_subparts(item["text"])), "errors": item_errors}
        records.append(record)
        errors.extend(item_errors)
result = {"schema": "stemrobin188-author-coverage@1", "ticket": "STEMROBIN-188", "assignment": "SAME188-6", "book": "9-10g", "lesson": "geo910-c2-s3-n68", "role": "bounded-text-author-self-check-not-independent-review", "objectsRequired": 13, "objectsCovered": len(records), "counts": {"source_prose_objects": sum(r["target"].startswith("prose[") for r in records), "exercises": sum(r["kind"] == "exercise" for r in records), "rewritten_prose_text_objects": sum(r["kind"] == "p" and r["text_changed"] for r in records), "retained_nontext_prose_objects": sum(r["kind"] in ["fig", "cap"] and not r["text_changed"] for r in records)}, "native_text_contract": "edition.validate_text", "objects": records, "errors": errors, "authorPreservationChecksPass": not errors and len(records) == 13, "independentReviewPerformed": False, "wholeLessonApproved": False, "published": False}
print(json.dumps(result, ensure_ascii=False, indent=2))
sys.exit(0 if result["authorPreservationChecksPass"] else 1)
